DEFAULTS = {"host": "localhost", "port": 8000, "debug": False}

def build_config(file_values=None, env_values=None):
    config = DEFAULTS.copy()
    if env_values:
        config.update(env_values)
    if file_values:
        config.update(file_values)
    return config

