from .pricing import line_total

def order_total(lines, coupon_percent=0):
    subtotal = sum(line_total(line["unit_price"], line["quantity"]) for line in lines)
    if coupon_percent:
        subtotal -= coupon_percent
    return round(subtotal, 2)
